From f2f0e22812821617f40a2346013f5579263954d5 Mon Sep 17 00:00:00 2001
From: Christoph Wolk <cwo.kde@posteo.net>
Date: Thu, 21 May 2026 10:31:08 +0200
Subject: [PATCH 1/4] applets/kicker: provide api for importing favorite
 ordering

The kicker backend saves the ordering of favorites outside appletsrc (in
kactivitymanagerd-statsrc), but using the applet id as part of the key.
This means that when the settings are (supposed to be) imported from
another instance, the favorite ordering is not copied. This applies to
two cases primarily: when using Alternatives to switch launchers, and
when cloning the panel. We have an existing heuristic that tries to
guess what the right one might be, but this is not very robust (it just
takes the newest data that might fit, so might be from a different
applet) and currently also loses data from other activities.

To make this robust, we need to know where to import the data from. We
add a methods to import favorite orderings from one applet instance
as saved in kactivitymanagerd-statsrc, and add it to another instance.
The old heuristic remains, as it might still be useful to provide an
initial ordering for newly created applets (i.e. not directly imported
from an existing one).

CCBUG: 514303
---
 applets/kicker/kastatsfavoritesmodel.cpp | 36 ++++++++++++++++++++++++
 applets/kicker/kastatsfavoritesmodel.h   |  1 +
 2 files changed, 37 insertions(+)

diff --git a/applets/kicker/kastatsfavoritesmodel.cpp b/applets/kicker/kastatsfavoritesmodel.cpp
index 224337a54c..eedd6557a5 100644
--- a/applets/kicker/kastatsfavoritesmodel.cpp
+++ b/applets/kicker/kastatsfavoritesmodel.cpp
@@ -496,6 +496,30 @@ public:
         cfg->sync();
     }

+    static void importOrderingFromApplet(uint oldInstanceId, uint newInstanceId, const QString &pluginName)
+    {
+        qCDebug(KICKER_DEBUG) << "Importing ordering from applet id" << oldInstanceId << "to applet id " << newInstanceId;
+        const auto cfg = KSharedConfig::openConfig(QStringLiteral("kactivitymanagerd-statsrc"));
+        const auto allGroups = cfg->groupList();
+        auto groupNamePart = QStringLiteral(".favorites.instance-%1-").arg(oldInstanceId);
+        for (const QStringView groupName : allGroups) {
+            if (groupName.contains(groupNamePart)) {
+                // the group names look like "Favorites-org.kde.plasma.kicker.favorites.instance-58-1bd5bb42-187c-4c77-a746-c9644c5da866"
+                const QStringList split = QString(groupName).split(u'-');
+                qDebug() << split;
+                if (split.length() >= 4) {
+                    QString activityId = split.mid(3).join(u"-");
+
+                    auto activityOrdering = KConfigGroup(cfg, groupName.toString()).readEntry("ordering", QStringList());
+                    ;
+                    qCDebug(KICKER_DEBUG) << "Importing ordering from applet id" << oldInstanceId << "for activity" << activityId;
+                    QString clientId = pluginName + QStringLiteral(".favorites.instance-") + QString::number(newInstanceId);
+                    saveOrdering(activityOrdering, clientId, activityId);
+                }
+            }
+        }
+    }
+
     KAStatsFavoritesModel *const q;
     KActivities::Consumer m_activities;
     Query m_query;
@@ -646,6 +670,18 @@ void KAStatsFavoritesModel::portOldFavorites(const QStringList &_ids)
     QTimer::singleShot(500, this, std::bind(&KAStatsFavoritesModel::initForClient, this, clientId));
 }

+void KAStatsFavoritesModel::importOrderingFromApplet(uint oldInstanceId, uint newInstanceId, const QString &pluginName)
+{
+    Private::importOrderingFromApplet(oldInstanceId, newInstanceId, pluginName);
+    if (!d) { // this will usually be called before d is created, but refresh it if it isn't
+        return;
+    }
+    if (m_activities->serviceStatus() == KActivities::Consumer::Running) {
+        auto clientId = d->m_clientId;
+        QTimer::singleShot(500, this, std::bind(&KAStatsFavoritesModel::initForClient, this, clientId));
+    }
+}
+
 void KAStatsFavoritesModel::addFavorite(const QString &id, int index)
 {
     qCDebug(KICKER_DEBUG) << "addFavorite" << id << index << " -->";
diff --git a/applets/kicker/kastatsfavoritesmodel.h b/applets/kicker/kastatsfavoritesmodel.h
index bb935cb973..01035211b2 100644
--- a/applets/kicker/kastatsfavoritesmodel.h
+++ b/applets/kicker/kastatsfavoritesmodel.h
@@ -66,6 +66,7 @@ public:
     Q_INVOKABLE void setFavoriteOn(const QString &id, const QString &activityId);

     Q_INVOKABLE void portOldFavorites(const QStringList &ids);
+    Q_INVOKABLE void importOrderingFromApplet(uint oldInstanceId, uint newInstanceId, const QString &pluginName);

     Q_INVOKABLE QStringList linkedActivitiesFor(const QString &id) const;

