From 266c482ae328331c86f0b7e20deb7e6fa682807b Mon Sep 17 00:00:00 2001
From: Christoph Wolk <cwo.kde@posteo.net>
Date: Thu, 21 May 2026 10:41:01 +0200
Subject: [PATCH 2/4] shell/alternativeshelper: pass old id to new kicker-based
 applet

Kicker-based launchers store extra data that relies on the applet's id
ouside appletsrc (more specifically in kactivitymanagerd-statsrc).
Without having the old applet id, the ordering of favorites may be lost
when replacing with an alternative. We have a way to pass this
information to the new applet using arguments, which are then forwarded
to the qml side and can be handled there. But we should only do this for
applets that need it, as some applets already use arguments for other
things.

So we test whether the old and new applets are kicker-based launchers
(kicker, kickerdash, or kickoff) and add the old appletid as an argument
to createApplet if so.
---
 shell/alternativeshelper.cpp | 14 ++++++++++++--
 1 file changed, 12 insertions(+), 2 deletions(-)

diff --git a/shell/alternativeshelper.cpp b/shell/alternativeshelper.cpp
index fd911c9bf3..ac8ffeeede 100644
--- a/shell/alternativeshelper.cpp
+++ b/shell/alternativeshelper.cpp
@@ -40,7 +40,8 @@ QQuickItem *AlternativesHelper::applet() const

 void AlternativesHelper::loadAlternative(const QString &plugin)
 {
-    if (plugin == m_applet->pluginMetaData().pluginId() || m_applet->isContainment()) {
+    auto oldPluginId = m_applet->pluginMetaData().pluginId();
+    if (plugin == oldPluginId || m_applet->isContainment()) {
         return;
     }

@@ -61,7 +62,16 @@ void AlternativesHelper::loadAlternative(const QString &plugin)

     const QPoint newPos = appletItem->mapToItem(contItem, QPointF(0, 0)).toPoint();

-    auto newApplet = cont->createApplet(plugin, {}, QRectF(newPos, QSizeF()));
+    const QStringList launcherPlugins{QStringLiteral("org.kde.plasma.kicker"),
+                                      QStringLiteral("org.kde.plasma.kickerdash"),
+                                      QStringLiteral("org.kde.plasma.kickoff")};
+
+    Plasma::Applet *newApplet;
+    if (launcherPlugins.indexOf(oldPluginId) == -1 && launcherPlugins.indexOf(plugin)) {
+        newApplet = cont->createApplet(plugin, {}, QRectF(newPos, QSizeF()));
+    } else {
+        newApplet = cont->createApplet(plugin, {m_applet->id()}, QRectF(newPos, QSizeF()));
+    }

     if (newApplet) {
         newApplet->setGlobalShortcut(shortcut);
